(7492527, 1193345, 181814, '<td valign="top">very unique lion with two different colors of eyes.</td>', 'very unique lion with two different colors of eyes.', '2017-01-16 20:06:12.000000', NULL, 1),
(7492528, 1193090, 181814, '<td valign="top">I would venture a guess that  this is not what I think the theme is about , even if it were, the focus is completely off and is not very interesting to look at.</td>', 'I would venture a guess that  this is not what I think the theme is about , even if it were, the focus is completely off and is not very interesting to look at.', '2017-01-16 20:07:34.000000', NULL, 1),
(7492529, 1193406, 181814, '<td valign="top">The right side of the photograph is very under exposed, you can barely see any detail of the eye which is the subject matter of this theme. The focus is not very well done either.</td>', 'The right side of the photograph is very under exposed, you can barely see any detail of the eye which is the subject matter of this theme. The focus is not very well done either.', '2017-01-16 20:08:29.000000', NULL, 1),
(7492530, 1193009, 181814, '<td valign="top">I think you tried to over sharpen this creating a lot of noise throughout the photograph.</td>', 'I think you tried to over sharpen this creating a lot of noise throughout the photograph.', '2017-01-16 20:09:15.000000', NULL, 1),
(7492531, 1193403, 181814, '<td valign="top">the composition of this photograph is not very well done in my opinion. I don''t like how the persons head is cut in half and the eyes are very underexposed and cannot be distinguished in the shadows. The focus is completely off.</td>', 'the composition of this photograph is not very well done in my opinion. I don''t like how the persons head is cut in half and the eyes are very underexposed and cannot be distinguished in the shadows. The focus is completely off.', '2017-01-16 20:11:00.000000', NULL, 1),
(7492532, 1192759, 181814, '<td valign="top">Very nice set of eyes with excellent focus, I think some harsh lighting has caused overexposed portions of her face.</td>', 'Very nice set of eyes with excellent focus, I think some harsh lighting has caused overexposed portions of her face.', '2017-01-16 20:11:46.000000', NULL, 1),
