(7492534, 1193209, 181814, '<td valign="top">I like the model and the facial expressions however the subject of the photograph which I assume is the eyes are underexposed and not very well focused.</td>', 'I like the model and the facial expressions however the subject of the photograph which I assume is the eyes are underexposed and not very well focused.', '2017-01-16 20:12:32.000000', NULL, 1),
(7492535, 1193301, 181814, '<td valign="top">I would venture a guess that this is not on theme, I see no eyes whatsoever.</td>', 'I would venture a guess that this is not on theme, I see no eyes whatsoever.', '2017-01-16 20:13:15.000000', NULL, 1),
(7492536, 1193399, 181814, '<td valign="top">I don''t know if this is supposed to be some sort of joke but I''m not impressed. This photograph could probably do very well in an abstract contest.</td>', 'I don''t know if this is supposed to be some sort of joke but I''m not impressed. This photograph could probably do very well in an abstract contest.', '2017-01-16 20:15:43.000000', NULL, 1),
(7492537, 1193412, 181814, '<td valign="top">This is a great looking photograph that captures the dogs eyes really well. From the photographs I was also far which is about three quarters of them this is by far the best entry in my opinion. You''re getting a perfect 10 from me for sure.</td>', 'This is a great looking photograph that captures the dogs eyes really well. From the photographs I was also far which is about three quarters of them this is by far the best entry in my opinion. You''re getting a perfect 10 from me for sure.', '2017-01-16 20:16:48.000000', NULL, 1),
